import type { AdRunnerManifest, BootstrapConfiguration, Placement } from "../specification/types.js"; import "../adapters/index.js"; import { dispatchAdRunnerEvent } from "./events.js"; import { resolvePlacementTarget } from "./placement.js"; import { PlacementRouter, type RouteResult } from "./router.js";
export class AdRunnerRuntime { manifest:AdRunnerManifest|null=null; private disabled=false; private mounted=new Set<string>(); private history=new Map<string,RouteResult[]>(); private observer?:MutationObserver; constructor(public siteId:string, private baseUrl=""){} async start(){ if(!this.disabled&&this.manifest&&this.mounted.size) return; this.disabled=false; const bootstrap=await this.fetchJSON<BootstrapConfiguration>(`${this.baseUrl}/v1/sites/${encodeURIComponent(this.siteId)}/bootstrap.json`); const manifestUrl=new URL(bootstrap.manifest, this.baseUrl||window.location.href).href; this.manifest=await this.fetchJSON<AdRunnerManifest>(manifestUrl); if(!this.manifest.settings.enabled||this.disabled) return; await this.mountPlacements(); if(this.manifest.settings.observe_dom!==false) this.observe(); this.dispatch("ready",{site:this.siteId,version:this.manifest.version}); }
 stop(){this.disabled=true; this.observer?.disconnect();} getStatus(){return{site:this.siteId,disabled:this.disabled,version:this.manifest?.version??null,mounted:[...this.mounted]};} getRouteHistory(slot:string){return this.history.get(slot)??[];} async refresh(slot:string){this.mounted.delete(slot); await this.mount(slot);} async mount(slot:string){const p=this.manifest?.placements.find(x=>x.id===slot||x.anchor===slot); if(p) await this.mountOne(p);} private async mountPlacements(){for(const p of [...(this.manifest?.placements??[])].filter(p=>p.enabled).sort((a,b)=>b.priority-a.priority)) if(this.deviceMatches(p.devices)) await this.mountOne(p);} private async mountOne(p:Placement){ if(this.mounted.has(p.id)) return; const target=resolvePlacementTarget(p); if(!target||!this.manifest){this.dispatch("missing-slot",{site:this.siteId,placement:p.id,anchor:p.anchor}); return;} this.mounted.add(p.id); const router=new PlacementRouter(this.manifest,(n,d)=>this.dispatch(n,{site:this.siteId,version:this.manifest?.version,...d})); let selection:any=null; try{ if(this.manifest.spec==="ad-runner/2") selection=await this.fetchJSON(`${this.baseUrl}/v1/sites/${encodeURIComponent(this.siteId)}/slots/${encodeURIComponent(p.id)}/select`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({manifest_version:this.manifest.version})} as any); }catch(e){ this.dispatch("selection-fallback",{placement:p.id,error:String(e),policy:p.fallback_policy??"manifest-weighted"}); } const result=await router.route(p,target,{manifest:this.manifest,site:this.siteId,version:this.manifest.version,selection,reportOutcome:async(body:any)=>{if(selection) await fetch(`${this.baseUrl}/v1/sites/${encodeURIComponent(this.siteId)}/slots/${encodeURIComponent(p.id)}/outcome`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});},emit:(n,d)=>this.dispatch(n,{site:this.siteId,...d})}); this.history.set(p.anchor,[...(this.history.get(p.anchor)??[]),result]); if(!result.filled&&this.manifest.settings.collapse_empty_slots) target.removeAttribute("data-ad-runner-active"); }
 private observe(){this.observer?.disconnect(); this.observer=new MutationObserver(()=>this.mountPlacements().catch(()=>{})); this.observer.observe(document.documentElement,{childList:true,subtree:true});}
 private deviceMatches(devices=["all"]){if(devices.includes("all")) return true; const mobile=window.matchMedia("(max-width: 767px)").matches; return mobile?devices.includes("mobile"):devices.includes("desktop");} private async fetchJSON<T>(url:string, init?:RequestInit){const r=await fetch(url,init); if(!r.ok) throw new Error(`Ad Runner request failed: ${r.status}`); return r.json() as Promise<T>;} private dispatch(name:string,detail:unknown){dispatchAdRunnerEvent(name,detail); fetch(`${this.baseUrl}/v1/sites/${encodeURIComponent(this.siteId)}/events`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({name:name.startsWith("adrunner:")?name:`adrunner:${name}`,detail})}).catch(()=>{});} }
declare global{interface Window{AdRunner?:AdRunnerRuntime}} const script=document.currentScript as HTMLScriptElement|null; const siteId=script?.dataset.adRunnerSite; const base=script?.dataset.adRunnerBase??(script?.src?new URL(script.src).origin:""); if(siteId){window.AdRunner=new AdRunnerRuntime(siteId,base); window.AdRunner.start().catch(e=>dispatchAdRunnerEvent("manifest-error",{site:siteId,error:String(e)}));}
